import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易尚氏學 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易尚氏學 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"classics/shangshi/044.md","filePath":"classics/shangshi/044.md"}'),s={name:"classics/shangshi/044.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>重坎故日蹇。坤在西南。五往居坤中。得中有應。放曰利西南。艮居東北。三陽窮於上而多兇。故不利東北。大人謂五。往得尊位。故利於出見。傳所謂往有功也。往五當位居中。故貞吉。</p><p>彖曰。蹇。雞也。險在前也。見險而能止。知矣哉。蹇利西南。往得中也。不利東北。其道窮也。利見大人。往有功也。當位員吉。以正邦也。蹇之時用大矣哉。</p><p>坎險又止。故曰見險而能止。此卦義也。虞翻於利不利之故。蓋茫然莫解。復以參同契月出庚之說。解利西南。月滅癸之說。解不利東北。豈知茲所謂西南確指坤位。坤為邦。五居坤中。故曰正邦。而翻則曰月生西南。夫月於三日出庚。庚豈西南哉。真管輅所謂美而偽也。</p><p>象曰。山上有水。蹇 君子以反身修德。</p><p>見險而止。反身修德。以俟之而已。文言云。進德修業。乾三雲。君子終日乾乾夕惕若。修德之事也。艮為身。反身者反而求諸己。不徒止而不前也。艮身象。艮彖雲。艮其背不獲其身。以艮為身也。故易林需之坎雲。名困身辱。勞無所得。坎中爻艮。艮為名。為身。坎隱伏。故名困身辱。虞翻用卦變。以坤為身。不知艮亦為身也。</p><p>初六。往黎。來譽。</p><p>四不應。二至四坎。初臨之。故往蹇。來居初。靜而不動。則有譽也。又為名。故曰譽。</p><h3 id="象曰。往蹇來譽。宜時也。" tabindex="-1">象曰。往蹇來譽。宜時也。 <a class="header-anchor" href="#象曰。往蹇來譽。宜時也。" aria-label="Permalink to “象曰。往蹇來譽。宜時也。”">​</a></h3><p>宜時。正義作宜待。釋文雲。張氏作宜時。鄭本作宜待時。虞同。茲從張氏。艮為時。宜時者。謂時宜如此也。阮校雲。石經待也二字。漫漶。而不言上有宜宇。可見鄭虞讀似非。</p><p>六二。王臣蹇蹇。匪躬之故。</p><p>艮為臣。五為王。二應五。故曰王臣。艮為憧僕。古臣僕不分。故艮亦為臣。二臨重坎。故曰王臣蹇蹇。蹇蹇言劬勞也。艮為躬。匪躬之故。言所以劬勞如此者。乃從王事。匪為私也。艮臣象。損上九雲。得臣無家。小過六二雲。遇其臣。遁六三雲。畜臣妾吉。皆以艮為臣也。</p><h3 id="象曰。-王巨蹇蹇。終無尤也。" tabindex="-1">象曰。 王巨蹇蹇。終無尤也。 <a class="header-anchor" href="#象曰。-王巨蹇蹇。終無尤也。" aria-label="Permalink to “象曰。 王巨蹇蹇。終無尤也。”">​</a></h3><p>有應故無尤。尤古音信。詩部風大夫君子。無我有尤。與下之協。此與上時下之協。與詩同。故正義上象作宜待非。</p><p>九三。往蹇。來反。</p><p>往遇險。反據下二陰則利也。故曰往蹇來反。</p><h3 id="象曰。往蹇來反。內喜之也。" tabindex="-1">象曰。往蹇來反。內喜之也。 <a class="header-anchor" href="#象曰。往蹇來反。內喜之也。" aria-label="Permalink to “象曰。往蹇來反。內喜之也。”">​</a></h3><p>內謂下二陰。陰欲承陽。故曰內喜之。釋來反之故也。</p><p>六四。往蹇。來連。</p><p>正義。馬雲連亦難也。王弼雲。往來皆難。是亦訓連為難。蓋四居上下坎之間。故往來皆難。荀爽謂與至尊相連。朱子謂連於九三者皆非也。又屯上六雲。泣血漣如。淮南子引作連如。蓋與此義同。亦連為難之一證。</p><h3 id="象曰。往蹇來連。當位實也。" tabindex="-1">象曰。往蹇來連。當位實也。 <a class="header-anchor" href="#象曰。往蹇來連。當位實也。" aria-label="Permalink to “象曰。往蹇來連。當位實也。”">​</a></h3><p>坎為實。當位實者。言四位當。惟所值上下皆實。故進退難也。坎剛中故為實。易林屯之師雲。李梅冬實。師震為李梅。坎為冬為實也。舊解皆以乾為實。致此句義不明瞭。豈知此賓字謂坎。上下坎。方能明來往皆難之義也。</p><p>九五。大蹇。用來。</p><p>當位居尊。故曰大蹇。陰以陽為朋。陽往陰中。故曰朋來。虞翻以下卦伏兌為朋。豈知象傳曰中節。即謂五居坤中。如合符節。釋朋義也。</p><h3 id="象曰。大蹇朋來。以中節也。言五在陰中。陰陽相遇。如符節之合。" tabindex="-1">象曰。大蹇朋來。以中節也。言五在陰中。陰陽相遇。如符節之合。 <a class="header-anchor" href="#象曰。大蹇朋來。以中節也。言五在陰中。陰陽相遇。如符節之合。" aria-label="Permalink to “象曰。大蹇朋來。以中節也。言五在陰中。陰陽相遇。如符節之合。”">​</a></h3><p>上六。往蹇。來碩。吉。利見大人。</p><p>上窮故往蹇。來碩謂應三。三陽故曰碩。爾雅釋詁。碩大也。陽大故曰碩。利見大人。謂順五。五為大人。</p><h3 id="象曰。往蹇來頂。志在內也。利見大人。以從貴也。" tabindex="-1">象曰。往蹇來頂。志在內也。利見大人。以從貴也。 <a class="header-anchor" href="#象曰。往蹇來頂。志在內也。利見大人。以從貴也。" aria-label="Permalink to “象曰。往蹇來頂。志在內也。利見大人。以從貴也。”">​</a></h3><p>應三故曰在內。三體坎。故曰志在內。五天子位。故曰從貴。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
